internal fun readInputValue(v: WireValue): InputValue {
    val (tag, payload) = v.variant()
    return when (tag) {
        "text" -> {
            InputValue.Text(Rd.string(payload, 0, -1))
        }

        "boolean" -> {
            InputValue.Boolean(Rd.bool(payload))
        }

        "choice" -> {
            InputValue.Choice((if (payload.json == JsonNull) null else Rd.string(payload, 0, -1)))
        }

        "number" -> {
            InputValue.Number(Rd.f64(payload))
        }

        else -> {
            refused()
        }
    }
}

internal fun writeInputValue(
    w: WireOutput,
    value: InputValue,
) {
    when (value) {
        is InputValue.Text -> {
            w.beginObject()
            w.name("text")
            w.string(value.value, 0, -1)
            w.endObject()
        }

        is InputValue.Boolean -> {
            w.beginObject()
            w.name("boolean")
            w.bool(value.value)
            w.endObject()
        }

        is InputValue.Choice -> {
            w.beginObject()
            w.name("choice")
            if (value.value == null) {
                w.nullValue()
            } else {
                w.string(value.value, 0, -1)
            }
            w.endObject()
        }

        is InputValue.Number -> {
            w.beginObject()
            w.name("number")
            w.number(value.value.toString())
            w.endObject()
        }
    }
}

