                    `activation` = payload.member("activation")?.let { f -> (if (f.json == JsonNull) null else readActionSpec(f)) } ?: null,
                    `badge` = payload.member("badge")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
                    `detail` = payload.member("detail")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
                    `iconToken` =
                        payload.member("icon_token")?.let { f ->
                            (
                                if (f.json ==
                                    JsonNull
                                ) {
                                    null
                                } else {
                                    Rd.string(f, 0, -1)
                                }
                            )
                        } ?: null,
                    `id` =
                        payload.member("id")?.let { f ->
                            (
                                if (f.json ==
                                    JsonNull
                                ) {
