                    `title` = Rd.string(payload.required("title"), 0, -1),
                    `tone` = readPresentationTone(payload.required("tone")),
                )
            }
            readPayload()
        }

        "Qr" -> {
            fun readPayload(): PresentationNode.Qr {
                payload.objectFields(
                    setOf(
                        "accessibility",
                        "capture_placeholder",
                        "capture_submit_label",
                        "error_correction",
                        "id",
