                                } else {
                                    readPresentationQrErrorCorrection(f)
                                }
                            )
                        }
                            ?: null,
                    `id` = Rd.identifier(Rd.string(payload.required("id"), 0, -1)),
                    `label` = payload.member("label")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
                    `payloads` = Rd.list(payload.required("payloads"), 0, -1) { e0 -> Rd.string(e0, 0, -1) },
                    `placement` = payload.member("placement")?.let { f -> (if (f.json == JsonNull) null else readQrPlacement(f)) } ?: null,
                    `purpose` = readPresentationQrPurpose(payload.required("purpose")),
                    `size` = payload.member("size")?.let { f -> (if (f.json == JsonNull) null else readPresentationQrSize(f)) } ?: null,
                )
            }
            readPayload()
        }

        "Confirmation" -> {
            fun readPayload(): PresentationNode.Confirmation {
                payload.objectFields(setOf("accessibility", "cancel", "confirm", "id", "warning"), false)
                return PresentationNode.Confirmation(
                    `accessibility` = readAccessibilitySpec(payload.required("accessibility")),
                    `cancel` = readActionSpec(payload.required("cancel")),
                    `confirm` = readActionSpec(payload.required("confirm")),
