        }

        "Slider" -> {
            fun readPayload(): PresentationNode.Slider {
                payload.objectFields(
                    setOf("accessibility", "binding_id", "label", "maximum", "maximum_icon", "minimum", "minimum_icon", "step", "value"),
                    false,
                )
                return PresentationNode.Slider(
                    `accessibility` = readAccessibilitySpec(payload.required("accessibility")),
                    `bindingId` = Rd.identifier(Rd.string(payload.required("binding_id"), 0, -1)),
                    `label` = Rd.string(payload.required("label"), 0, -1),
                    `maximum` = Rd.f64(payload.required("maximum")),
                    `maximumIcon` =
                        payload.member("maximum_icon")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
                    `minimum` = Rd.f64(payload.required("minimum")),
