        }

        "Progress" -> {
            fun readPayload(): PresentationNode.Progress {
                payload.objectFields(setOf("accessibility", "label", "value"), false)
                return PresentationNode.Progress(
                    `accessibility` = readAccessibilitySpec(payload.required("accessibility")),
