                    `value` = payload.member("value")?.let { f -> (if (f.json == JsonNull) null else Rd.f64(f)) } ?: null,
                )
            }
            readPayload()
        }

        else -> {
            refused()
        }
    }
}

internal fun writePresentationNode(
