internal fun readPresentationRow(v: WireValue): PresentationRow {
    v.objectFields(
        setOf(
            "accessibility",
            "activation",
            "controls",
            "detail",
            "enabled",
            "fallback_text",
            "icon_token",
            "image_data",
            "info",
            "secondary_actions",
            "selected",
            "subtitle",
            "title",
        ),
        false,
    )
    return PresentationRow(
        `accessibility` = readAccessibilitySpec(v.required("accessibility")),
        `activation` = v.member("activation")?.let { f -> (if (f.json == JsonNull) null else readActionSpec(f)) } ?: null,
        `controls` = Rd.list(v.required("controls"), 0, -1) { e0 -> readPresentationNode(e0) },
        `detail` = v.member("detail")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
        `enabled` = Rd.bool(v.required("enabled")),
        `fallbackText` = v.member("fallback_text")?.let { f -> (if (f.json == JsonNull) null else Rd.string(f, 0, -1)) } ?: null,
